String[] movies = {"Inception", "Avatar", "Titanic", "Jaws", "Up"};

// Print all movies
for (int i = 0; i < movies.length; i++) {
    System.out.println(movies[i]);
}

// Print just the third movie
System.out.println("Third movie: " + movies[2]);

// Change the second movie
movies[1] = "The Matrix";
